insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('GM', 'default', 'The Gambia reference chart of accounts', '{}'::jsonb, true, 'companies', array['GM-IFRS-IS', 'GM-IFRS-SFP']::text[], null, 'There is no legal chart of accounts in The Gambia. The IFRS Foundation''s jurisdiction profile says IFRS Standards are required for commercial banks and permitted for all other companies, that SMEs may use the IFRS for SMEs Standard, and that the Companies Act 1955 does not specify the accounting standards to apply; the Gambia Institute of Chartered Accountants (GICA) and the Financial Reporting Oversight Board were created by a 2013 Act, and the profile dates from June 2016, so the current standard-setting position should be confirmed with GICA. This chart is original: four digits, blocked so that each range reaches one line of the IFRS-based statements below, with the accounts a Gambian company actually keeps — VAT input and output tax, import VAT owed to the Gambia Revenue Authority at the border, the net VAT due to or from the Authority after a return, withholding tax, PAYE and social security contributions payable.', 'ifrs-gambia')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

