values
  ('GM', 'GM-P-15', 'Purchase, standard rate 15 %, deductible', '{}'::jsonb, 'A local purchase at the general rate, used in the business of a VAT registrant', 'percent', 15, 'purchase', 'domestic', date '2013-01-01', null, 'The GRA brochure, § 8: VAT registrants are able to claim input VAT credits, the VAT paid on any expenditure being recoverable from GRA. Which purchases are blocked (entertainment, passenger vehicles…) is not stated in the sources this pack could open and no blocked-input code is offered; see the README.', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-brochure', null, null, null, null),
  ('GM', 'GM-P-EX', 'Purchase, exempt', '{}'::jsonb, 'An exempt supply bought for the business, such as a life or health insurance premium', 'percent', 0, 'purchase', 'exempt', date '2013-01-01', null, 'The GRA brochure, § 6: exempt supplies carry no VAT, so there is no input tax to claim.', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-brochure', null, null, null, null),
  ('GM', 'GM-P-IMP', 'Import of goods, VAT paid at the border', '{}'::jsonb, 'VAT charged on the importation of taxable goods, paid to the Authority before release and claimed as input tax', 'percent', 15, 'purchase', 'import', date '2013-01-01', null, 'The GRA brochure, § 5: VAT is collected at the point of imports; § 10: import VAT is payable before the goods are released. The Authority''s customs clearance is not modelled; the VAT is posted against a payable account (2125) the user settles when the border payment is made.', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-brochure', null, null, null, null),
  ('GM', 'GM-S-15', 'Sale, standard rate 15 %', '{}'::jsonb, 'The general rate on a taxable supply made in The Gambia', 'percent', 15, 'sale', 'domestic', date '2013-01-01', null, 'The GRA brochure, § 2: the standard VAT rate is 15 percent and applies to all goods and services unless they are specifically exempted; § 4: all taxable supplies by a registered supplier are VAT inclusive, the VAT element being the selling price divided by 115 and multiplied by 15. Ekwo computes the tax on a price excluding VAT; the invoice shows the VAT-inclusive total. Box numbers are this pack''s own (see the README).', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-brochure', null, null, null, null),
  ('GM', 'GM-S-EX', 'Sale, exempt', '{}'::jsonb, 'An exempt supply: basic foods, unprocessed agricultural products, education, prescription drugs, medical, dental, veterinary and optical services, life and health insurance, residential rent, domestic transport (not tourism), small electricity and water consumption', 'percent', 0, 'sale', 'exempt', date '2013-01-01', null, 'The GRA brochure, § 6: exempt supplies are goods and services on which no VAT is charged — basic foods such as rice, sugar, flour, cooking oil, onions and potatoes; educational services; prescription drugs; medical, dental, veterinary and optical services; agriculture and aquaculture products, inputs and equipment, and unprocessed agricultural and aquacultural products; life and health insurance; financial services not rendered for a fee or commission; domestic transportation and ferry services excluding tourism-related transport; rental or supply of residential properties; monthly domestic electricity consumption below 1,000 kWh and water below 250 cubic metres. The list is the brochure''s summary and not the Schedule of the Act; one code carries all of them and the user picks it per line. Input tax attributable to an exempt supply is not deductible.', 'E', null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-brochure', null, null, null, null),
  ('GM', 'GM-S-Z-EXP', 'Sale, zero-rated (export)', '{}'::jsonb, 'A supply of goods or services exported from The Gambia', 'percent', 0, 'sale', 'export', date '2013-01-01', null, 'The GRA brochure, § 2, and the Domestic Taxes FAQs: zero percent is applied to exports of goods and services. The brochure (§ 12) lets a registrant with at least 50 % of its supplies in the preceding twelve months zero-rated, such as an exporter, apply for a refund of its input tax. The conditions of export (evidence, customs entry) are not stated in the sources this pack could open and are not modelled.', 'G', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-brochure', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

insert into tax_posting_templates
  (tax_template_id, document_kind, posting_type, factor_percent, account_code,
   declaration_box, declaration_boxes, box_factor_percent, report_code, sequence)
select t.id,
       v.document_kind::tax_document_kind,
       v.posting_type::tax_posting_type,
       v.factor_percent::numeric,
       v.account_code::text,
       v.declaration_box::text,
       v.declaration_boxes::text[],
       v.box_factor_percent::numeric,
       v.report_code::text,
       v.sequence::integer
  from (values
    ('GM-P-15', 'invoice', 'base', 100, null, '2', array['2']::text[], 100, 'GM-VAT-RETURN', 10),
    ('GM-P-15', 'invoice', 'tax', 100, '1150', '2', array['2']::text[], 100, 'GM-VAT-RETURN', 20),
    ('GM-P-15', 'credit_note', 'base', 100, null, '2', array['2']::text[], -100, 'GM-VAT-RETURN', 10),
    ('GM-P-15', 'credit_note', 'tax', 100, '1150', '2', array['2']::text[], -100, 'GM-VAT-RETURN', 20),
    ('GM-P-EX', 'invoice', 'base', 100, null, null, null, 100, null, 10),
    ('GM-P-EX', 'credit_note', 'base', 100, null, null, null, 100, null, 10),
    ('GM-P-IMP', 'invoice', 'base', 100, null, '3', array['3']::text[], 100, 'GM-VAT-RETURN', 10),
    ('GM-P-IMP', 'invoice', 'tax', 100, '1150', '3', array['3']::text[], 100, 'GM-VAT-RETURN', 20),
    ('GM-P-IMP', 'invoice', 'tax', -100, '2125', null, null, 100, null, 30),
    ('GM-P-IMP', 'credit_note', 'base', 100, null, '3', array['3']::text[], -100, 'GM-VAT-RETURN', 10),
    ('GM-P-IMP', 'credit_note', 'tax', 100, '1150', '3', array['3']::text[], -100, 'GM-VAT-RETURN', 20),
    ('GM-P-IMP', 'credit_note', 'tax', -100, '2125', null, null, 100, null, 30),
    ('GM-S-15', 'invoice', 'base', 100, null, '1S', array['1S']::text[], 100, 'GM-VAT-RETURN', 10),
    ('GM-S-15', 'invoice', 'tax', 100, '2100', '1S', array['1S']::text[], 100, 'GM-VAT-RETURN', 20),
    ('GM-S-15', 'credit_note', 'base', 100, null, '1S', array['1S']::text[], -100, 'GM-VAT-RETURN', 10),
    ('GM-S-15', 'credit_note', 'tax', 100, '2100', '1S', array['1S']::text[], -100, 'GM-VAT-RETURN', 20),
    ('GM-S-EX', 'invoice', 'base', 100, null, 'EX', array['EX']::text[], 100, 'GM-VAT-RETURN', 10),
    ('GM-S-EX', 'credit_note', 'base', 100, null, 'EX', array['EX']::text[], -100, 'GM-VAT-RETURN', 10),
    ('GM-S-Z-EXP', 'invoice', 'base', 100, null, 'ZE', array['ZE']::text[], 100, 'GM-VAT-RETURN', 10),
    ('GM-S-Z-EXP', 'credit_note', 'base', 100, null, 'ZE', array['ZE']::text[], -100, 'GM-VAT-RETURN', 10)
  ) as v (tax_code, document_kind, posting_type, factor_percent, account_code,
          declaration_box, declaration_boxes, box_factor_percent, report_code, sequence)
  join tax_templates t on t.country = 'GM' and t.code = v.tax_code
on conflict (tax_template_id, document_kind, posting_type, sequence) do update set
  factor_percent     = excluded.factor_percent,
  account_code       = excluded.account_code,
  declaration_box    = excluded.declaration_box,
  declaration_boxes  = excluded.declaration_boxes,
  box_factor_percent = excluded.box_factor_percent,
  report_code        = excluded.report_code;

insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('GM', 'GM-VAT-RETURN', 'Monthly Value Added Tax return', array['month']::declaration_period[], 'month'::declaration_period, date '2013-01-01', null, 'The GRA brochure, § 10: VAT registrants file the prescribed VAT return form and pay all amounts due monthly, even where there were no transactions (§ 13); § 11: returns are submitted at any Domestic Taxes Department office. The prescribed return form itself could not be opened from the machine this pack was written on, so the box numbers below are this pack''s own presentation of output tax, input tax and the balance, and not the numbering of a GRA form. The gap is recorded in this pack''s README.', true,'day_of_month_after_period'::filing_deadline_rule, 15, null, 'The GRA brochure, § 10: the due date for each month''s filing and payment is the 15th of the following month; the Domestic Taxes FAQs word the same rule as 15 days after the month end. Import VAT is payable before the goods are released. Penalties and the treatment of a 15th that falls on a non-working day are not modelled.', 'vat-brochure', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

