  ('GM', 'GM-VAT-RETURN', 'ZE', 'base', 'Zero-rated supplies — exports', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'The value of exports of goods and services, taxed at zero percent (brochure § 2). A reporting row of this pack.', 'vat-brochure'),
  ('GM', 'GM-VAT-RETURN', 'EX', 'base', 'Exempt supplies', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'The value of the exempt supplies of the brochure''s § 6. A reporting row of this pack.', 'vat-brochure'),
  ('GM', 'GM-VAT-RETURN', '1S', 'base', 'Standard-rated supplies — value', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'The sales on which the output VAT is charged at 15 % (brochure § 2). A reporting row of this pack.', 'vat-brochure'),
  ('GM', 'GM-VAT-RETURN', '1S', 'tax', 'Output VAT on standard-rated supplies', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Output VAT on sales, net of credit notes given (brochure §§ 2, 4, 5).', 'vat-brochure'),
  ('GM', 'GM-VAT-RETURN', '1', 'total', 'Box 1 — Output VAT', '{}'::jsonb, 50, null, array['1S:tax']::text[], '{}'::text[], null, null, false, false, null, 'Total output VAT of the period. This pack''s own total.', 'vat-brochure'),
  ('GM', 'GM-VAT-RETURN', '2', 'base', 'Standard-rated local purchases — value', '{}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'The purchases on which input VAT is incurred. A reporting row of this pack.', 'vat-brochure'),
  ('GM', 'GM-VAT-RETURN', '2', 'tax', 'Box 2 — Input VAT on domestic purchases', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Input VAT credit on local expenditure (brochure § 8).', 'vat-brochure'),
  ('GM', 'GM-VAT-RETURN', '3', 'base', 'Imports of goods — value', '{}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'The customs value of imports on which import VAT is paid at the border (brochure §§ 5, 10). A reporting row of this pack.', 'vat-brochure'),
  ('GM', 'GM-VAT-RETURN', '3', 'tax', 'Box 3 — Input VAT on imports', '{}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Import VAT claimed as input tax (brochure §§ 5, 8).', 'vat-brochure'),
  ('GM', 'GM-VAT-RETURN', '4', 'total', 'Box 4 — Total input VAT', '{}'::jsonb, 100, null, array['2:tax', '3:tax']::text[], '{}'::text[], null, null, false, false, null, 'Box 2 plus box 3. This pack''s own total.', 'vat-brochure'),
  ('GM', 'GM-VAT-RETURN', '5', 'total', 'Box 5 — VAT payable or repayable', '{}'::jsonb, 110, null, array['1']::text[], array['4']::text[], null, null, false, false, null, 'Box 1 minus box 4. A positive figure is payable on the 15th of the following month; a negative figure is input VAT in excess, which the registrant may claim as a refund when it has been in credit for three consecutive months or exports at least half of its supplies (brochure §§ 8, 12).', 'vat-brochure')
on conflict (country, report_code, box, kind) do update set
