values
  ('GM-IFRS-IS', 'GM', 'default', 'Statement of profit or loss', 'income_statement', 'IFRS-SME', date '2013-01-01', null, 'Statement of profit or loss — an original presentation by nature of expense that follows IAS 1 / section 4 of the IFRS for SMEs. The Gambia has no statutory format: the IFRS Foundation''s jurisdiction profile (June 2016) says IFRS Standards are required for commercial banks and permitted for other companies, and that SMEs may use the IFRS for SMEs Standard. The lines are the pack''s own and should be confirmed with GICA.', 'ifrs-gambia', null, null, '{}'::jsonb),
  ('GM-IFRS-SFP', 'GM', 'default', 'Statement of financial position', 'balance_sheet', 'IFRS-SME', date '2013-01-01', null, 'Statement of financial position — an original presentation by nature of expense that follows IAS 1 / section 4 of the IFRS for SMEs. The Gambia has no statutory format: the IFRS Foundation''s jurisdiction profile (June 2016) says IFRS Standards are required for commercial banks and permitted for other companies, and that SMEs may use the IFRS for SMEs Standard. The lines are the pack''s own and should be confirmed with GICA.', 'ifrs-gambia', 'combined', 'Result of the current financial year', '{}'::jsonb)
